'use strict';
// Presentation accounts live on this device. Hosted Site access stays platform-managed.
const ACCOUNT_STORE='kaincheck-demo-accounts-v1',ACCOUNT_SESSION='kaincheck-demo-session-v1',GUEST_STATE='kaincheck-demo-v1';
let accountMode='welcome',accountBusy=false,accountOperation=0;
function readDemoAccounts(){try{const data=JSON.parse(localStorage.getItem(ACCOUNT_STORE));return Array.isArray(data)?data.filter(a=>a&&typeof a.id==='string'&&typeof a.email==='string'&&typeof a.username==='string'&&typeof a.salt==='string'&&typeof a.passwordHash==='string'):[];}catch{return [];}}
function readDemoSession(){try{const session=JSON.parse(localStorage.getItem(ACCOUNT_SESSION));if(session?.guest===true)return {guest:true};if(typeof session?.accountId==='string'&&readDemoAccounts().some(a=>a.id===session.accountId))return {accountId:session.accountId};}catch{}return null;}
let accountSession=readDemoSession();
function currentDemoAccount(){return accountSession?.accountId?readDemoAccounts().find(a=>a.id===accountSession.accountId)||null:null;}
function accountStateKey(){return accountSession?.accountId?'kaincheck-account-state-'+accountSession.accountId:GUEST_STATE;}
function loadKaincheckState(){try{return JSON.parse(localStorage.getItem(accountStateKey()));}catch{return null;}}
function persistKaincheckState(value){localStorage.setItem(accountStateKey(),JSON.stringify(value));if(accountSession?.accountId){const accounts=readDemoAccounts(),account=accounts.find(a=>a.id===accountSession.accountId);if(account&&account.username!==value.name){account.username=value.name;localStorage.setItem(ACCOUNT_STORE,JSON.stringify(accounts));}}}
function freshKaincheckState(){const value=initial(),account=currentDemoAccount();if(account)value.name=account.username;return value;}
function accountSectionMarkup(){const account=currentDemoAccount();return `<section class="account-section"><h2>Account</h2><p>${account?`Signed in as <strong>${esc(account.username)}</strong><br>${esc(account.email)}`:'You’re exploring as a guest.'}</p><small>Demo account · saved on this device</small>${account?'':`<div class="account-inline-actions"><button class="secondary" data-account-action="register">Create account</button><button class="secondary" data-account-action="signin">Sign in</button></div>`}<button class="account-logout" data-account-action="logout">${ic('logout')}Log out</button></section>`;}
function renderAccountGate(){const nav=document.querySelector('#nav');nav.hidden=true;nav.innerHTML='';const register=accountMode==='register',signin=accountMode==='signin';const form=register||signin;document.querySelector('#app').innerHTML=`<section class="account-screen"><a class="account-brand" href="#" data-account-action="welcome"><span>✦</span>KainCheck</a>${form?`<button class="text-btn account-back" data-account-action="welcome">← Back</button>`:''}<div class="account-art" aria-hidden="true"><span>🌿</span><i>✦</i><b>small steps, your way</b></div><p class="account-eyebrow">YOUR FOOD. YOUR PACE. YOUR VIBE.</p><h1>${register?'Make room for you.':signin?'Welcome back.':'Feel good about<br>your everyday.'}</h1><p class="account-subtitle">${register?'Create your KainCheck demo account.':signin?'Sign in to your saved demo account.':'Familiar food, flexible movement, and a coach that gets your vibe.'}</p>${form?`<form id="account-form" data-mode="${accountMode}">${register?'<label class="field"><span>Username</span><input id="account-username" name="username" minlength="2" maxlength="24" autocomplete="nickname" required></label>':''}<label class="field"><span>Email</span><input id="account-email" name="email" type="email" maxlength="254" autocomplete="email" required></label><label class="field"><span>Password</span><div class="key-field"><input id="account-password" name="password" type="password" minlength="8" maxlength="128" autocomplete="${register?'new-password':'current-password'}" required><button type="button" data-account-action="show-password" aria-label="Show password">Show</button></div></label>${register?'<label class="field"><span>Confirm password</span><input id="account-confirm" name="confirm" type="password" minlength="8" maxlength="128" autocomplete="new-password" required></label>':''}<p id="account-error" class="account-error" role="alert"></p><button class="primary account-submit" type="submit">${register?'Create account':'Sign in'}</button></form><p class="account-switch">${register?'Already registered?':'New here?'} <button class="text-btn" data-account-action="${register?'signin':'register'}">${register?'Sign in':'Create account'}</button></p>`:`<div class="account-welcome-actions"><button class="primary" data-account-action="register">Create account</button><button class="secondary" data-account-action="signin">Sign in</button></div>`}<button class="text-btn account-guest" data-account-action="guest">Continue demo as guest</button><p class="account-demo-note">Presentation demo · Accounts and app data stay on this device. Use a demo password.</p></section>`;document.querySelector('#app').scrollTop=0;}
function showAccountMode(mode){accountOperation++;accountBusy=false;accountMode=mode;closeModal();resetEpoch++;activeChatController?.abort();activeChatController=null;chatBusy=false;renderAccountGate();}
function hexBytes(bytes){return [...bytes].map(x=>x.toString(16).padStart(2,'0')).join('');}
async function demoPasswordHash(password,salt){if(!globalThis.crypto?.subtle)throw Error('Open the hosted or installed KainCheck app to create an account.');const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);const bytes=await crypto.subtle.deriveBits({name:'PBKDF2',salt:Uint8Array.from(salt.match(/.{2}/g),x=>parseInt(x,16)),iterations:210000,hash:'SHA-256'},material,256);return hexBytes(new Uint8Array(bytes));}
function samePasswordHash(a,b){if(a.length!==b.length)return false;let diff=0;for(let i=0;i<a.length;i++)diff|=a.charCodeAt(i)^b.charCodeAt(i);return diff===0;}
function restoreAccountState(saved,username){state=saved?.version===1?{...initial(),...saved,coach:{...initial().coach,...saved.coach}}:initial();if(!Array.isArray(state.meals)||!Array.isArray(state.messages)||!Array.isArray(state.plan))state=initial();if(username)state.name=username;initializeCoachProfiles();}
function enterDemoSession(session,saved,username){accountSession=session;localStorage.setItem(ACCOUNT_SESSION,JSON.stringify(session));accountOperation++;accountBusy=false;resetEpoch++;activeChatController?.abort();activeChatController=null;chatBusy=false;connectionKeys.clear();coachSettingsDrafts.clear();draftApiKey='';settingsDraft=null;closeModal();restoreAccountState(saved,username);save();screen='today';document.querySelector('#nav').hidden=false;render();toast(session.guest?'Explore at your own pace.':'Welcome, '+state.name+'.');}
async function submitDemoAccount(form){if(accountBusy)return;const mode=form.dataset.mode,register=mode==='register',data=new FormData(form),email=String(data.get('email')||'').trim().toLowerCase(),password=String(data.get('password')||''),username=String(data.get('username')||'').trim();const error=document.querySelector('#account-error'),button=form.querySelector('button[type="submit"]');error.textContent='';if(register&&(username.length<2||username.length>24)){error.textContent='Use a username from 2 to 24 characters.';return;}if(register&&password!==String(data.get('confirm')||'')){error.textContent='Your passwords do not match.';return;}const accounts=readDemoAccounts(),existing=accounts.find(a=>a.email===email);if(register&&existing){error.textContent='This email already has a demo account on this device. Sign in instead.';return;}if(!register&&!existing){error.textContent='Email or password is incorrect.';return;}accountBusy=true;const operation=++accountOperation;button.disabled=true;button.textContent=register?'Creating account…':'Signing in…';try{let account=existing;if(register){const salt=hexBytes(crypto.getRandomValues(new Uint8Array(16))),passwordHash=await demoPasswordHash(password,salt);if(operation!==accountOperation)return;account={id:crypto.randomUUID(),username,email,salt,passwordHash};const saved=accounts.length===0?JSON.parse(JSON.stringify(state)):initial();saved.name=username;localStorage.setItem('kaincheck-account-state-'+account.id,JSON.stringify(saved));try{localStorage.setItem(ACCOUNT_STORE,JSON.stringify([...accounts,account]));}catch(e){localStorage.removeItem('kaincheck-account-state-'+account.id);throw e;}enterDemoSession({accountId:account.id},saved,username);}else{const candidate=await demoPasswordHash(password,account.salt);if(operation!==accountOperation)return;if(!samePasswordHash(candidate,account.passwordHash))throw Error('Email or password is incorrect.');let saved;try{saved=JSON.parse(localStorage.getItem('kaincheck-account-state-'+account.id));}catch{}enterDemoSession({accountId:account.id},saved,account.username);}}catch(e){if(operation===accountOperation&&error.isConnected)error.textContent=e.name==='QuotaExceededError'?'This device has no storage space for the account. Free some space and try again.':e.message||'Could not complete sign-in. Try again.';}finally{if(operation===accountOperation){accountBusy=false;if(button.isConnected){button.disabled=false;button.textContent=register?'Create account':'Sign in';}}}}
function logoutDemoAccount(){save();accountOperation++;accountBusy=false;resetEpoch++;activeChatController?.abort();activeChatController=null;chatBusy=false;disposeFoodScan();connectionKeys.clear();coachSettingsDrafts.clear();configuredPawanKeyPromise=null;draftApiKey='';settingsDraft=null;closeModal();accountSession=null;localStorage.removeItem(ACCOUNT_SESSION);state=initial();initializeCoachProfiles();screen='today';accountMode='welcome';render();toast('Logged out. Your demo data stays on this device.');}
function installDemoAccounts(){iconPaths.logout='<path d="M10 4H4v16h6M14 8l4 4-4 4M8 12h10"/>';document.addEventListener('click',e=>{const button=e.target.closest('[data-account-action]');if(!button)return;e.preventDefault();const action=button.dataset.accountAction;if(['welcome','register','signin'].includes(action)){showAccountMode(action);return;}if(action==='guest'){let saved;try{saved=JSON.parse(localStorage.getItem(GUEST_STATE));}catch{}enterDemoSession({guest:true},saved);return;}if(action==='logout'){logoutDemoAccount();return;}if(action==='show-password'){const input=document.querySelector('#account-password');input.type=input.type==='password'?'text':'password';button.textContent=input.type==='password'?'Show':'Hide';button.setAttribute('aria-label',input.type==='password'?'Show password':'Hide password');}});document.addEventListener('submit',e=>{if(e.target.id==='account-form'){e.preventDefault();submitDemoAccount(e.target);}});}
